return [{ json: {
  webhook_base: 'https://REPLACE-N8N-DOMAIN/webhook/price-approval',
  shopify_admin: 'https://admin.shopify.com/store/REPLACE_STORE/products',
  default_min_margin_pct: 15, default_max_change_pct: 10, beat_pct: 1, default_premium_pct: 5,
  min_change_abs: 5, min_change_pct: 0.5, oos_raise_pct: 4, low_stock: 10, cooldown_hours: 24,
  max_proposals_per_run: 25, user_agent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124 Safari/537.36'
} }];

const jobs = [];
for (const { json: p } of $('Read Products Sheet').all()) {
  if (!p.sku || String(p.active ?? 'yes').toLowerCase() === 'no') continue;
  for (const n of [1, 2, 3]) {
    const url = String(p[`comp${n}_url`] || '').trim();
    if (!/^https?:\/\//.test(url)) continue;
    jobs.push({ json: { sku: p.sku, our_price: Number(p.our_price) || 0, competitor: p[`comp${n}_name`] || new URL(url).hostname.replace('www.', ''), url } });
  }
}
return jobs;

const job = $('Loop Over Competitor URLs').first().json;
const r = $input.first().json || {};
const html = String(r.body ?? r.data ?? '');
const num = s => { const n = Number(String(s ?? '').replace(/[^\d.]/g, '')); return n > 0 ? n : null; };
let price = null, mrp = null, inStock = null, method = '';
// 1) JSON-LD
for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  try {
    const walk = o => { if (!o || price) return; if (Array.isArray(o)) return o.forEach(walk);
      if (o['@graph']) walk(o['@graph']);
      const off = o.offers ? (Array.isArray(o.offers) ? o.offers[0] : o.offers) : null;
      if (off && (off.price || off.lowPrice)) { price = num(off.price || off.lowPrice); inStock = off.availability ? /InStock|LimitedAvailability/i.test(off.availability) : null; method = 'json-ld'; } };
    walk(JSON.parse(m[1].trim()));
  } catch (e) {}
  if (price) break;
}
// 2) meta tags
if (!price) { const m = html.match(/(?:itemprop=["']price["'][^>]*content|property=["'](?:product:price:amount|og:price:amount)["'][^>]*content)=["']([\d.,]+)/i);
  if (m) { price = num(m[1]); method = 'meta'; } }
// 3) marketplace selectors
if (!price) { const m = html.match(/class=["'][^"']*(?:a-price-whole|priceToPay|Nx9bqj|_30jeq3|product-price|price-item--sale|money)[^"']*["'][^>]*>\s*(?:<[^>]+>)*\s*(?:₹|Rs\.?|&#8377;|INR)?\s*([\d,]+(?:\.\d{1,2})?)/i);
  if (m) { price = num(m[1]); method = 'selector'; } }
// 4) ₹ regex near "price"
if (!price) { const m = html.match(/price[^<]{0,80}?(?:₹|Rs\.?|&#8377;)\s?([\d,]{2,9}(?:\.\d{1,2})?)/i); if (m) { price = num(m[1]); method = 'regex'; } }
const mm = html.match(/(?:M\.?R\.?P|a-text-price|yRaY8j|_3I9_wc)[^₹\d]{0,80}(?:₹|Rs\.?)\s?([\d,]+)/i); if (mm) mrp = num(mm[1]);
if (inStock === null) inStock = /out of stock|currently unavailable|sold out|notify me/i.test(html) ? false : (html ? true : null);
const suspicious = !!price && job.our_price > 0 && (price < job.our_price * 0.3 || price > job.our_price * 3);
const blocked = !r.statusCode || r.statusCode >= 400 || /captcha|robot check|access denied/i.test(html.slice(0, 5000));
const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
const around = (text.match(/.{0,300}(?:₹|Rs\.?)\s?[\d,]+.{0,300}/g) || []).slice(0, 8).join(' … ').slice(0, 6000);
return [{ json: { ...job, price, mrp, in_stock: inStock, method, http_status: r.statusCode || 0, blocked,
  needs_ai: !blocked && (!price || suspicious) && around.length > 50, ai_text: around, scraped_at: new Date().toISOString() } }];

values.content:
You extract the CURRENT selling price of one product from cleaned e-commerce page text (Indian sites, ₹).
Ignore EMI amounts, "save ₹X", coupon values, bank offers, shipping fees and prices of other or related products. Prefer the price next to "Add to cart" or "Buy now".
Return ONLY JSON: {"price": number|null, "mrp": number|null, "in_stock": boolean|null, "confidence": number (0-1), "note": string (max 12 words)}

=Our product's approximate price: ₹{{ $json.our_price }}
Competitor: {{ $json.competitor }}
Page text excerpts:
{{ $json.ai_text }}

parameters.jsCode:
const j = $('Parse Price from Page').first().json;
const a = $input.first().json.message?.content || {};
const ok = a.price && (a.confidence ?? 0) >= 0.6 && a.price > j.our_price * 0.3 && a.price < j.our_price * 3;
return [{ json: { ...j, price: ok ? Number(a.price) : null, mrp: a.mrp || j.mrp, in_stock: a.in_stock ?? j.in_stock,
  method: ok ? 'ai' : 'failed', ai_note: a.note || '', ai_text: undefined } }];

const cfg = $('Set PriceOS Config').first().json;
const scraped = $input.all().map(i => i.json).filter(j => j.sku);
const recent = $('Read Past Proposals').all().map(i => i.json).filter(p => p.status === 'applied' && p.decided_at);
const r2 = x => Math.round(x * 100) / 100;
const round9 = (x, floor) => { if (x < 100) return r2(x); let v = Math.floor(x / 10) * 10 + 9; if (v > x + 0.01) v -= 10; if (v < floor) v = Math.ceil((floor - 9) / 10) * 10 + 9; return v; };
return $('Read Products Sheet').all().map(i => i.json).filter(p => p.sku && String(p.active ?? 'yes').toLowerCase() !== 'no').map(p => {
  const comps = scraped.filter(s => s.sku === p.sku);
  const valid = comps.filter(c => c.price && c.in_stock !== false);
  const our = Number(p.our_price) || 0, cost = Number(p.cost) || 0;
  const minM = Number(p.min_margin_pct) || cfg.default_min_margin_pct;
  const floor = r2(Math.max(cost * (1 + minM / 100), Number(p.floor_price) || 0, Number(p.map_price) || 0));
  const ceiling = r2(Number(p.ceiling_price) || our * 1.3);
  const maxChg = (Number(p.max_change_pct) || cfg.default_max_change_pct) / 100;
  const prices = valid.map(c => c.price).sort((a, b) => a - b);
  const lowest = prices[0] ?? null, median = prices.length ? prices[Math.floor(prices.length / 2)] : null;
  const strategy = String(p.strategy || 'beat_lowest').toLowerCase();
  const reasons = [];
  let target = our;
  if (strategy === 'hold') reasons.push('strategy = hold');
  else if (!comps.length) reasons.push('no competitor URLs');
  else if (!valid.length && comps.some(c => c.price && c.in_stock === false)) { target = our * (1 + cfg.oos_raise_pct / 100); reasons.push('all competitors out of stock → small raise'); }
  else if (!valid.length) reasons.push('no reliable competitor price today');
  else if (strategy === 'match_lowest') { target = lowest; reasons.push(`match lowest ₹${lowest}`); }
  else if (strategy === 'stay_premium') { target = lowest * (1 + (Number(p.premium_pct) || cfg.default_premium_pct) / 100); reasons.push(`premium over lowest ₹${lowest}`); }
  else { target = lowest - Math.max(1, lowest * cfg.beat_pct / 100); reasons.push(`beat lowest ₹${lowest}`); }
  const raw = target;
  if (target < floor) { target = floor; reasons.push(`floor ₹${floor} (margin/MAP)`); }
  if (target > ceiling) { target = ceiling; reasons.push(`ceiling ₹${ceiling}`); }
  if (Math.abs(target - our) / (our || 1) > maxChg) { target = target > our ? our * (1 + maxChg) : our * (1 - maxChg); reasons.push(`capped at ${maxChg * 100}%/day`); }
  if (Number(p.stock) > 0 && Number(p.stock) < cfg.low_stock && target < our) { target = our; reasons.push('low stock → no price cut'); }
  target = round9(Math.max(target, floor), floor);
  if ((our - target) / (our || 1) > maxChg + 1e-9 && target >= 100) target += 10;
  const lastApplied = recent.filter(x => x.sku === p.sku).map(x => new Date(x.decided_at).getTime()).sort((a, b) => b - a)[0];
  const cooling = lastApplied && (Date.now() - lastApplied) / 3600000 < cfg.cooldown_hours;
  if (cooling) reasons.push('changed in the last 24h (cooldown)');
  const delta = r2(target - our);
  const change = !cooling && strategy !== 'hold' && Math.abs(delta) >= Math.max(cfg.min_change_abs, our * cfg.min_change_pct / 100);
  const margin = v => v ? r2((v - cost) / v * 100) : null;
  return { json: { ...p, our_price: our, cost, floor, ceiling, max_change_pct: maxChg * 100, strategy, competitors: comps.map(c => ({ name: c.competitor,
    price: c.price, mrp: c.mrp, in_stock: c.in_stock, method: c.method, url: c.url })), lowest, median, valid_count: valid.length,
    position: lowest === null ? 'unknown' : our < lowest ? 'cheapest' : our === lowest ? 'tied' : `+${r2((our - lowest) / lowest * 100)}% vs lowest`,
    rule_raw: r2(raw), rule_price: target, delta, change, reasons, margin_now: margin(our), margin_rule: margin(target) } };
});

const all = $input.all().map(i => i.json);
const failed = all.flatMap(p => p.competitors.filter(c => !c.price).map(c => `${p.sku}@${c.name}`));
const under = all.filter(p => p.lowest !== null && p.our_price > p.lowest * 1.05).sort((a, b) => (b.our_price / b.lowest) - (a.our_price / a.lowest)).slice(0, 5);
return [{ json: { text: `:bar_chart: *Price watch – ${$now.toFormat('dd LLL')}*\n${all.length} SKUs · ${all.reduce((a, p) => a + p.competitors.length, 0)} competitor pages · ` +
  `${all.filter(p => p.change).length} change candidates (approval cards follow)\n` +
  (under.length ? `*Most overpriced vs lowest:*\n${under.map(p => `• ${p.sku}: ₹${p.our_price} vs ₹${p.lowest} (${p.position})${p.floor > p.lowest ? ' · floor prevents matching' : ''}`).join('\n')}\n` : '') +
  (failed.length ? `:warning: Could not read ${failed.length} page(s): ${failed.slice(0, 8).join(', ')}` : ':white_check_mark: All competitor pages parsed') } }];

const cfg = $('Set PriceOS Config').first().json;
const p = $('Change Proposed?').item.json;
const ai = $json.message?.content || {};
const r2 = x => Math.round(x * 100) / 100;
let price = Number(ai.suggested_price) || p.rule_price;
const notes = [];
if (price < p.floor) { price = p.floor; notes.push('AI price below floor → clamped'); }
if (price > p.ceiling) { price = p.ceiling; notes.push('AI price above ceiling → clamped'); }
const maxC = p.max_change_pct / 100;
if (Math.abs(price - p.our_price) / p.our_price > maxC) { price = p.our_price * (1 + Math.sign(price - p.our_price) * maxC); notes.push('max daily change cap'); }
if (price >= 100) { let v = Math.floor(price / 10) * 10 + 9; if (v > price + 0.01) v -= 10; price = v < p.floor ? Math.ceil((p.floor - 9) / 10) * 10 + 9 : v; }
if ((p.our_price - price) / p.our_price > maxC + 1e-9 && price >= 100) price += 10;   // rounding must not breach the cap
price = r2(Math.max(price, p.floor));
const delta = r2(price - p.our_price);
const go = Math.abs(delta) >= Math.max(cfg.min_change_abs, p.our_price * cfg.min_change_pct / 100);
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const id = `PP-${$now.toFormat('yyLLdd')}-${String(p.sku).replace(/\W/g, '').slice(0, 12)}-${hex(4)}`;
return { json: { ...p, proposal_id: id, token: hex(24), proposed_price: price, delta, delta_pct: r2(delta / p.our_price * 100), go,
  margin_new: price ? r2((price - p.cost) / price * 100) : null, ai_price: Number(ai.suggested_price) || null, ai_confidence: ai.confidence || '',
  rationale: ai.rationale || p.reasons.join('; '), risk_flags: [...(ai.risk_flags || []), ...notes] } };

const p = $('Apply Guardrails').item.json;
const cfg = $('Set PriceOS Config').first().json;
const inr = v => v === null || v === undefined ? '–' : '₹' + Number(v).toLocaleString('en-IN');
const link = a => `${cfg.webhook_base}?id=${p.proposal_id}&t=${p.token}&a=${a}`;
const comp = p.competitors.map(c => `• ${c.name}: ${c.price ? inr(c.price) : 'n/a'}${c.in_stock === false ? ' (OOS)' : ''}${c.method === 'ai' ? ' ·AI' : ''}`).join('\n') || 'none';
return { json: { fallback: `Reprice ${p.sku}: ${inr(p.our_price)} → ${inr(p.proposed_price)}`, blocks: [
  { type: 'header', text: { type: 'plain_text', text: `${p.delta < 0 ? '🔻' : '🔺'} Reprice ${p.product_title || p.sku}`.slice(0, 150) } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Price*\n${inr(p.our_price)} → *${inr(p.proposed_price)}* (${p.delta_pct > 0 ? '+' : ''}${p.delta_pct}%)` },
    { type: 'mrkdwn', text: `*Margin*\n${p.margin_now}% → ${p.margin_new}%` },
    { type: 'mrkdwn', text: `*Guardrails*\nfloor ${inr(p.floor)} · ceiling ${inr(p.ceiling)}` },
    { type: 'mrkdwn', text: `*Position today*\n${p.position}` } ] },
  { type: 'section', text: { type: 'mrkdwn', text: `*Competitors*\n${comp}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*AI (${p.ai_confidence || '?'})*: ${p.rationale}${p.risk_flags.length ? `\n:warning: ${p.risk_flags.join(' · ')}` : ''}` } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `SKU ${p.sku} · velocity ${p.units_sold_7d || '–'}/7d · stock ${p.stock || '–'} · expires in 24h · ${p.proposal_id}` }] },
  { type: 'actions', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: `✅ Approve ${inr(p.proposed_price)}` }, url: link('approve') },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: '❌ Reject' }, url: link('reject') },
    ...(p.shopify_product_id ? [{ type: 'button', text: { type: 'plain_text', text: 'Open in Shopify' }, url: `${cfg.shopify_admin}/${p.shopify_product_id}` }] : []) ] } ] } };

const shop = 'REPLACE_STORE.myshopify.com';
const q = $('On Approve or Reject Link Click').first().json.query || {};
const p = $input.first()?.json || {};
const a = String(q.a || '').toLowerCase();
let reason = '';
if (!p.proposal_id) reason = 'Proposal not found';
else if (p.status !== 'pending') reason = `Already ${p.status}`;
else if (!p.token || p.token !== q.t) reason = 'Invalid link';
else if ((Date.now() - new Date(p.created_at).getTime()) / 3600000 > 24) reason = 'Proposal expired (older than 24h). Tomorrow\'s run will re-evaluate.';
else if (a === 'approve' && Number(p.proposed_price) < Number(p.floor)) reason = 'Price is below the floor. Blocked by guardrail.';
else if (!['approve', 'reject'].includes(a)) reason = 'Unknown action';
const gid = (t, id) => String(id).startsWith('gid://') ? String(id) : `gid://shopify/${t}/${id}`;
return [{ json: { ...p, act: a, valid: !reason, reason, shop,
  gql: { query: 'mutation($productId: ID!, $variants: [ProductVariantsBulkInput!]!) { productVariantsBulkUpdate(productId: $productId, variants: $variants) { productVariants { id price } userErrors { field message } } }',
    variables: { productId: gid('Product', p.shopify_product_id), variants: [{ id: gid('ProductVariant', p.shopify_variant_id), price: Number(p.proposed_price).toFixed(2) }] } } } }];

const p = $('Validate Approval').first().json;
const r = $input.first().json;
const res = r.body?.data?.productVariantsBulkUpdate;
const errs = [...(res?.userErrors || []).map(e => e.message), ...(r.body?.errors || []).map(e => e.message || e)];
const ok = r.statusCode === 200 && res && !errs.length;
return [{ json: { ...p, shopify_ok: ok, shopify_result: ok ? `set to ${res.productVariants?.[0]?.price}` : `HTTP ${r.statusCode}: ${errs.join('; ') || 'unknown error'}` } }];
